        $uid, $s['name'], $s['email'], $hashedPass, $s['phone'], $s['phone_code'],
        $s['whatsapp'], $s['country_id'], $s['selling_products'], $s['company_name'],
        $s['website'], $s['city'], $s['membership_level'], $s['lead_stage'], $now, $now
    );

    if ($stmt->execute()) {
        $newId = $conn->insert_id;
        $supplierIds[] = $newId;
        echo "  Inserted supplier #{$newId}: {$s['company_name']} ({$uid})\n";

        $logoFile = $s['logo'];
        $conn->query("UPDATE users SET company_logo='" . $conn->real_escape_string($logoFile) . "' WHERE id={$newId}");
    } else {
        echo "  ERROR inserting supplier {$s['company_name']}: " . $stmt->error . "\n";
        $supplierIds[] = null;
    }
    $stmt->close();
