echo "\nInserting " . count($products) . " products...\n";
$prodCount = 0;

foreach ($products as $p) {
    $suppIdx = $p['supplier_idx'];
    if (!isset($supplierIds[$suppIdx]) || $supplierIds[$suppIdx] === null) {
        echo "  SKIP: Supplier index {$suppIdx} not found.\n";
        continue;
    }
    $suppId = $supplierIds[$suppIdx];
    $now = date('Y-m-d H:i:s', strtotime('-' . rand(1, 60) . ' days'));

    $stmt = $conn->prepare("INSERT INTO products (supplier_id, category_id, name, slug, description, specifications, main_image, min_order_quantity, min_order_unit, price_range, supply_ability, delivery_time, packaging, port, payment_terms, certifications, is_featured, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)");
    $featured = $p['featured'];
    $catId = $p['cat'];
    $pName = $p['name'];
    $pSlug = $p['slug'];
    $pDesc = $p['desc'];
    $pSpecs = $p['specs'];
    $pImg = $p['img'];
    $pMoq = $p['moq'];
    $pUnit = $p['unit'];
    $pPrice = $p['price'];
    $pSupply = $p['supply'];
    $pDelivery = $p['delivery'];
    $pPack = $p['packaging'];
    $pPort = $p['port'];
    $pPay = $p['payment'];
    $pCerts = $p['certs'];
    $now2 = $now;
    $stmt->bind_param('iisssssissssssssiss',
        $suppId, $catId, $pName, $pSlug, $pDesc, $pSpecs,
        $pImg, $pMoq, $pUnit, $pPrice, $pSupply,
        $pDelivery, $pPack, $pPort, $pPay, $pCerts,
        $featured, $now, $now2
    );

    if ($stmt->execute()) {
        $prodCount++;
        if ($prodCount % 10 == 0) echo "  Inserted {$prodCount} products...\n";
    } else {
        echo "  ERROR inserting product {$p['name']}: " . $stmt->error . "\n";
    }
    $stmt->close();
}

echo "\nDone! Inserted " . count($supplierIds) . " suppliers and {$prodCount} products.\n";

$conn->close();
